function FooterAnchor({ link }: { link: FooterLink }) {
  if (link.external) {
    return (
      <a href={link.href} className={LINK_CLASS} rel="noreferrer">
        {link.label}
      </a>
    );
  }
  return (
    <FramerockLink href={link.href} className={LINK_CLASS}>
      {link.label}
